source("workflow/common.R")
s <- readRDS(project$summary)$summary
ensure_parent(project$results_tex)
stopifnot(identical(s$group, project$groups))
lines <- c(
  "% Generated by manuscript/export-results.R. Do not edit.",
  sprintf("\\newcommand{\\ControlN}{%d}", s$n[1]),
  sprintf("\\newcommand{\\TreatmentN}{%d}", s$n[2]),
  sprintf("\\newcommand{\\ControlMean}{%.2f}", s$mean[1]),
  sprintf("\\newcommand{\\TreatmentMean}{%.2f}", s$mean[2]),
  "\\newcommand{\\SummaryTable}{%",
  "\\begin{tabular}{lrrr}\\toprule",
  "Group & $n$ & Mean & SD \\\\ \\midrule",
  sprintf("Control & %d & %.2f & %.2f \\\\", s$n[1], s$mean[1], s$sd[1]),
  sprintf("Treatment & %d & %.2f & %.2f \\\\", s$n[2], s$mean[2], s$sd[2]),
  "\\bottomrule\\end{tabular}%", "}"
)
writeLines(lines, project$results_tex)
